use crate::{require,run,sha_file,stem,valid_repo,valid_sha,write_json,Result};
use serde_json::{json,Value};
use std::{env,fs::{self,OpenOptions},io::{Read,Write},path::Path,process::Command};
use sha2::{Digest,Sha256};
pub fn api(repository:&str,path:&str,missing:bool)->Result<Option<Value>>{require(valid_repo(repository),"Invalid repository")?;let mut command=Command::new("gh");command.args(["api",&format!("repos/{repository}/{path}")]);let result=run(command)?;if !result.success{if missing&&String::from_utf8_lossy(&result.stderr).contains("(HTTP 404)"){return Ok(None);}return Err(format!("GitHub API read failed for {path}").into());}Ok(Some(serde_json::from_slice(&result.stdout)?))}
fn output(key:&str,value:bool)->Result<()>{if let Ok(path)=env::var("GITHUB_OUTPUT"){writeln!(OpenOptions::new().append(true).open(path)?,"{key}={value}")?;}Ok(())}
pub fn config()->Result<(String,String,String)>{let repository=env::var("GITHUB_REPOSITORY")?;let source=env::var("SOURCE_COMMIT")?;require(valid_repo(&repository)&&valid_sha(&source,40),"A valid repository and complete source commit are required")?;let tag=env::var("RELEASE_TAG").unwrap_or_else(|_|format!("inta-workspace-{}",&source[..12]));require(!tag.is_empty()&&tag.bytes().all(|c|c.is_ascii_alphanumeric()||b"._-".contains(&c))&&!tag.starts_with('-'),"Invalid release tag")?;Ok((repository,source,tag))}
pub fn check(root:&Path,phase:&str)->Result<Value>{
    require(["freshness","prepare","before","after"].contains(&phase),"Unknown publication phase")?;let(repository,source,tag)=config()?;let current=api(&repository,"git/ref/heads/main",false)?.unwrap()["object"]["sha"].as_str().ok_or("Missing current main identity")?.to_string();
    if phase=="freshness"{output("current",current==source)?;return Ok(json!({"sourceCommit":source,"currentMain":current,"current":current==source}));}
    if phase=="prepare"||phase=="before"{require(current==source,"A newer main revision exists; publication was stopped")?;}
    let release=api(&repository,&format!("releases/tags/{tag}"),true)?;let reference=api(&repository,&format!("git/ref/tags/{tag}"),true)?;let mut target=reference.map(|v|v["object"].clone());
    for _ in 0..8{let Some(object)=&target else{break;};if object["type"]=="commit"{break;}require(object["type"]=="tag","Release tag points to an unsupported Git object")?;let hash=object["sha"].as_str().ok_or("Missing annotated tag identity")?;require(valid_sha(hash,40),"Invalid annotated tag identity")?;target=Some(api(&repository,&format!("git/tags/{hash}"),false)?.unwrap()["object"].clone());}
    require(target.as_ref().is_none_or(|v|v["type"]=="commit"),"Annotated tag chain is too deep")?;let tagged=target.as_ref().and_then(|v|v["sha"].as_str());
    if phase=="prepare"&&release.as_ref().is_some_and(|r|r["draft"]==false){require(tagged==Some(&source),"Published immutable release points to another source commit")?;output("pending",false)?;return Ok(json!({"pending":false,"releaseUrl":release.as_ref().unwrap()["html_url"],"publishedCommit":tagged,"reason":"This exact source release is already published"}));}
    if phase=="prepare"||phase=="before"{require(tagged.is_none()||tagged==Some(&source),"Existing tag points to different source")?;if let Some(release)=&release{require(release["draft"]==true,"Release became public before publication")?;require(release["target_commitish"]==source,"Existing draft belongs to another source")?;}if phase=="prepare"{output("pending",true)?;}return Ok(json!({"pending":true,"sourceCommit":source,"tag":tag,"existingTag":tagged}));}
    let release=release.ok_or("Published release is missing")?;require(release["draft"]==false&&tagged==Some(&source),"Published release/tag does not match verified source")?;
    let prefix=stem(&source)?;let names:[String;4]=["-source.zip","-offline.html","-manifest.json","-SHA256SUMS.txt"].map(|suffix|format!("{prefix}{suffix}"));let mut rows=Vec::new();let assets=release["assets"].as_array().ok_or("Release asset list missing")?;
    for name in names{let matching:Vec<_>=assets.iter().filter(|a|a["name"]==name).collect();require(matching.len()==1,"Complete release asset is missing or duplicated")?;let url=matching[0]["browser_download_url"].as_str().ok_or("Download URL missing")?;require(url.starts_with(&format!("https://github.com/{repository}/releases/download/{tag}/")),"Release download URL is outside expected repository")?;let(expected,size)=sha_file(&root.join("dist/release").join(&name))?;let mut input=crate::network().get(url).call()?.into_reader();let mut digest=Sha256::new();let mut received=0;let mut buffer=vec![0;1024*1024];loop{let n=input.read(&mut buffer)?;if n==0{break;}received+=n as u64;require(received<=size,"Downloaded release exceeds recorded size")?;digest.update(&buffer[..n]);}require(received==size&&format!("{:x}",digest.finalize())==expected,"Downloaded release bytes differ")?;rows.push(json!({"name":name,"bytes":size,"sha256":expected,"url":url}));}
    let report=json!({"status":"success","sourceCommit":source,"tag":tag,"releaseUrl":release["html_url"],"assets":rows});write_json(&root.join("reports/release-publish.json"),&report)?;Ok(report)
}
pub fn publish(root:&Path)->Result<Value>{
    check(root,"before")?;let(repository,source,tag)=config()?;let prefix=stem(&source)?;let directory=root.join("dist/release");let mut assets:Vec<_>=fs::read_dir(&directory)?.filter_map(std::result::Result::ok).map(|e|e.path()).filter(|p|p.file_name().is_some_and(|n|n.to_string_lossy().starts_with(&prefix))).collect();assets.sort();require(assets.len()==4,"Expected exactly four validated release assets")?;
    let exists=api(&repository,&format!("releases/tags/{tag}"),true)?.is_some();let mut command=Command::new("gh");command.args(["release",if exists{"upload"}else{"create"},&tag]);command.args(&assets).args(["--repo",&repository]);if exists{command.arg("--clobber");}else{command.args(["--target",&source,"--title",&format!("INTA Rust workspace · {}",&source[..12]),"--notes-file"]).arg(directory.join("release-notes.md")).arg("--draft");}require(run(command)?.success,"Release asset publication failed; inspect draft before retry")?;
    let mut command=Command::new("gh");command.args(["release","edit",&tag,"--repo",&repository,"--draft=false"]);require(run(command)?.success,"Could not make verified release public")?;check(root,"after")
}
